package render

const viewerHTML = `<!doctype html>
<html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Wok · Render</title>
<style>
body.embed header,body.embed #status,body.embed .hint{display:none}body.embed main{padding:0}body.embed #screen{box-shadow:none}:root{color-scheme:dark;font:14px system-ui;background:#111315;color:#e6e8ea}body{margin:0}header{display:flex;align-items:center;gap:12px;padding:14px 20px;border-bottom:1px solid #30353a}strong{font-size:18px}form{display:flex;gap:8px;flex:1}input,select,button{font:inherit;color:inherit;background:#202429;border:1px solid #41474f;border-radius:6px;padding:8px}input{flex:1;min-width:80px}select{max-width:240px}button{cursor:pointer}button:hover{background:#323941}main{padding:18px;display:flex;justify-content:center}#screen{display:block;max-width:100%;height:auto;outline:none;background:#202429;box-shadow:0 3px 20px #0006}#screen:focus{outline:2px solid #8aaefa}#status{margin:10px 20px;color:#a8b2be;min-height:20px}#status.error{color:#ff9c9c}.hint{margin:0 20px;color:#838d98;font-size:12px}@media(max-width:700px){header{flex-wrap:wrap}form{flex-basis:100%}}
</style>
<header><strong>Wok</strong><label for="tabs">Tab</label><select id="tabs" aria-label="Browser tab"></select><button id="refresh" title="Refresh tab list">↻</button><form id="navigation"><input id="url" aria-label="Page URL" placeholder="https://example.com"><button>Go</button></form></header>
<p id="status" role="status">Connecting to browser…</p><p class="hint">Click the page to interact. Keyboard and scrolling are sent to the selected tab.</p><main><img id="screen" tabindex="0" alt="Live browser page; click to focus keyboard input"></main>
<script>
const viewerToken=new URLSearchParams(location.search).get('token');function withToken(value){const target=new URL(value,location.href);if(viewerToken&&target.origin===location.origin)target.searchParams.set('token',viewerToken);return target.href}const originalFetch=window.fetch.bind(window);function apiFetch(value,options){return originalFetch(withToken(value),options)}
const tabs=document.querySelector('#tabs'),screen=document.querySelector('#screen'),status=document.querySelector('#status'),url=document.querySelector('#url');let current=new URLSearchParams(location.search).get('tab')||'',tabInfo=[],queue=Promise.resolve(),editing=false,viewport=null;
if(new URLSearchParams(location.search).get('embed')==='1')document.body.classList.add('embed');
function report(message,error=false){status.textContent=message;status.className=error?'error':''}
function send(event){const tab=current;if(!tab)return;queue=queue.then(async()=>{const response=await apiFetch('/render/input?tab='+encodeURIComponent(tab),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(event)});if(!response.ok)throw Error(await response.text());report('Connected · '+(tabs.selectedOptions[0]?.textContent||'page'))}).catch(error=>report(error.message,true));return queue}
function select(){current=tabs.value;viewport=null;const selected=current;apiFetch('/render/viewport?tab='+encodeURIComponent(selected)).then(r=>{if(!r.ok)throw Error('Viewport unavailable');return r.json()}).then(v=>{if(current===selected)viewport=v}).catch(error=>report(error.message,true));const info=tabInfo.find(t=>(t.targetId||t.TargetID||t.id)===current);if(!editing)url.value=info?.url||info?.URL||'';screen.src=withToken('/render/stream?tab='+encodeURIComponent(current));report('Connected · '+(tabs.selectedOptions[0]?.textContent||'page'))}
async function refresh(){try{const response=await apiFetch('/render/tabs');if(!response.ok)throw Error(await response.text());tabInfo=await response.json();const prev=current;tabs.replaceChildren();for(const t of tabInfo){const option=document.createElement('option');option.value=t.targetId||t.TargetID||t.id;option.textContent=t.title||t.Title||t.url||t.URL||'Untitled';tabs.append(option)}if([...tabs.options].some(o=>o.value===prev))tabs.value=prev;if(!tabs.value){current='';screen.removeAttribute('src');report('No browser tabs open');return}if(tabs.value!==current||!screen.getAttribute('src'))select();else{if(!editing)url.value=tabInfo.find(t=>t.targetId===current)?.url||'';const selected=current;apiFetch('/render/viewport?tab='+encodeURIComponent(selected)).then(r=>r.json()).then(v=>{if(current===selected)viewport=v}).catch(()=>{})}}catch(error){report(error.message,true)}}
tabs.addEventListener('change',select);document.querySelector('#refresh').onclick=refresh;document.querySelector('#navigation').onsubmit=e=>{e.preventDefault();let value=url.value.trim();if(!/^[a-z][a-z\d+.-]*:/i.test(value))value='https://'+value;send({type:'navigate',url:value}).then(refresh)};url.onfocus=()=>editing=true;url.onblur=()=>editing=false;
function point(e){const r=screen.getBoundingClientRect(),w=viewport?.width||screen.naturalWidth,h=viewport?.height||screen.naturalHeight;return {x:Math.max(0,Math.min(w-1,(e.clientX-r.left)*w/r.width)),y:Math.max(0,Math.min(h-1,(e.clientY-r.top)*h/r.height))}}
let held=0,lastMove=0;const buttonName=e=>e.button===2?'right':e.button===1?'middle':'left',mods=e=>[e.ctrlKey?'ctrl':'',e.shiftKey?'shift':'',e.altKey?'alt':'',e.metaKey?'meta':''].filter(Boolean).join(',');
function mouse(kind,e){const tab=current,p=point(e),q=new URLSearchParams({tab,x:p.x,y:p.y,mods:mods(e)});if(kind==='move')q.set('buttons',[held&1?'left':'',held&2?'right':'',held&4?'middle':''].filter(Boolean).join(','));else q.set('button',buttonName(e));queue=queue.then(async()=>{const r=await apiFetch('/render/'+kind+'?'+q,{method:'POST'});if(!r.ok)throw Error(await r.text())}).catch(error=>report(error.message,true))}
screen.addEventListener('pointerdown',e=>{e.preventDefault();screen.focus();held=e.buttons;screen.setPointerCapture(e.pointerId);mouse('mousedown',e)});screen.addEventListener('pointerup',e=>{e.preventDefault();held=e.buttons;mouse('mouseup',e);if(screen.hasPointerCapture(e.pointerId))screen.releasePointerCapture(e.pointerId)});screen.addEventListener('pointercancel',e=>{held=0;mouse('mouseup',e)});screen.addEventListener('pointermove',e=>{held=e.buttons;if(performance.now()-lastMove<40)return;lastMove=performance.now();mouse('move',e)});screen.addEventListener('contextmenu',e=>e.preventDefault());screen.draggable=false;
screen.addEventListener('wheel',e=>{e.preventDefault();const unit=e.deltaMode===1?16:e.deltaMode===2?screen.naturalHeight:1;send({type:'scroll',...point(e),deltaX:Math.max(-100000,Math.min(100000,e.deltaX*unit)),deltaY:Math.max(-100000,Math.min(100000,e.deltaY*unit))})},{passive:false});
screen.addEventListener('keydown',e=>{if(e.isComposing||['Control','Shift','Alt','Meta'].includes(e.key))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='v')return;if(e.ctrlKey||e.metaKey||e.altKey){e.preventDefault();const parts=[e.ctrlKey?'Ctrl':'',e.metaKey?'Meta':'',e.altKey?'Alt':'',e.shiftKey?'Shift':'',e.key].filter(Boolean);send({type:'key',key:parts.join('+')})}else if(e.key==='Tab'||e.key==='Escape'||e.key==='Enter'||e.key==='Backspace'||e.key==='Delete'||e.key==='Home'||e.key==='End'||e.key==='PageUp'||e.key==='PageDown'||e.key.startsWith('Arrow')||/^F\d+$/.test(e.key)){e.preventDefault();send({type:'key',key:e.shiftKey?'Shift+'+e.key:e.key})}else if(e.key.length===1){e.preventDefault();send({type:'text',text:e.key})}});screen.addEventListener('paste',e=>{e.preventDefault();send({type:'text',text:e.clipboardData.getData('text')})});screen.onerror=()=>report('Stream disconnected. Refresh tabs to reconnect.',true);refresh();setInterval(refresh,5000);
</script></html>`
